package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.OperacaoDtos.*; import br.com.tapeteskalke.service.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/ordens-producao") public class ProducaoController { private final ProducaoService service; private final PermissionService permissions; public ProducaoController(ProducaoService service,PermissionService permissions){this.service=service;this.permissions=permissions;} @GetMapping public ApiResponse<List<OrdemResponse>> list(){permissions.page("producao");return ApiResponse.ok(service.list());} @PostMapping public ResponseEntity<ApiResponse<OrdemResponse>> create(@Valid @RequestBody OrdemRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.create(r)));} @PostMapping("/{id}/finalizar") public ApiResponse<OrdemResponse> finish(@PathVariable String id){return ApiResponse.ok(service.finish(id));} @PostMapping("/{id}/cancelar") public ApiResponse<OrdemResponse> cancel(@PathVariable String id,@Valid @RequestBody CancelarRequest r){return ApiResponse.ok(service.cancel(id,r));} }